def simulate(capacity_map):
    # State
    stock = {p: info['opening_stock'] for p, info in prod_info.items()}
    queue = [] # list of [product, remaining, day]

    history = {day: {p: {} for p in prod_info} for day in days}

    for day in days:
        cap = capacity_map[day]

        # 1. Production arrives
        for p in prod_info:
            stock[p] += daily_prod_ord[day][p]['produced']

        # 2. Orders join the queue
        for p in prod_info:
            qty = daily_prod_ord[day][p]['ordered']
            if qty > 0:
                queue.append([p, qty, day])

        # 3. Dispatch
        # Sort: day placed (asc), then remaining quantity (asc), then product code (asc)
        queue.sort(key=lambda x: (x[2], x[1], x[0]))

        daily_shipped = {p: 0 for p in prod_info}
        remaining_cap = cap

        i = 0
        while i < len(queue):
            p, rem, day_placed = queue[i]
            weight = prod_info[p]['weight']

            # Max units possible by stock and capacity
            max_by_stock = stock[p]
            max_by_cap = int(remaining_cap // weight)

            shipped = min(rem, max_by_stock, max_by_cap)

            if shipped > 0:
                stock[p] -= shipped
                remaining_cap -= shipped * weight
                queue[i][1] -= shipped
                daily_shipped[p] += shipped

            if queue[i][1] == 0:
                queue.pop(i)
            else:
                i += 1

        # 4. Records
        for p in prod_info:
            backordered = sum(order[1] for order in queue if order[0] == p)
            history[day][p] = {
                'stock': stock[p],
                'backordered': backordered,
                'shipped': daily_shipped[p]
            }

    return history

