def simulate(prod_info, daily_data, production_mod=None):
    CAPACITY = 192950
    stocks = {p: prod_info[p]['opening_stock'] for p in prod_info}
    order_queue = [] 
    results = {}

    days = sorted(daily_data.keys())
    for day in days:
        # 1. Production arrives
        for p in prod_info:
            prod_qty = daily_data[day][p]['produced']
            if production_mod:
                prod_qty += production_mod.get((day, p), 0)
            stocks[p] += prod_qty

        # 2. Orders join the queue
        for p in prod_info:
            ordered_qty = daily_data[day][p]['ordered']
            if ordered_qty > 0:
                order_queue.append([day, ordered_qty, p])

        # 3. Dispatch
        remaining_capacity = CAPACITY
