            if shippable > 0:
                stocks[p] -= shippable
                remaining_capacity -= shippable * weight
                order_queue[i][1] -= shippable

            if order_queue[i][1] == 0:
                order_queue.pop(i)
            else:
                i += 1

        # 4. Records
