prod_data, prod_cols = get_table_data('Plant 2114, Period 11: Products')
weights = {r['product']: float(r['kg per unit']) for r in prod_data}

ledger_data, ledger_cols = get_table_data('Plant 2114, Period 11: Daily ledger')
state = {}
for r in ledger_data:
    if int(r['day']) == 154:
        state[r['product']] = {
            'stock': int(r['stock']),
            'backordered': int(r['backordered'])
        }

ob_data, ob_cols = get_table_data('Plant 2114, Period 11: Order book')
capacity_limit = 300000

current_stock = {p: s['stock'] for p, s in state.items()}
order_queue = [] # list of [day, qty, product]

for day in range(155, 162):
    for r in ob_data:
        if int(r['day']) == day:
            prod = r['product']
            current_stock[prod] += int(r['planned production'])

    for r in ob_data:
        if int(r['day']) == day:
            prod = r['product']
            qty = int(r['ordered'])
            if qty > 0:
                order_queue.append([day, qty, prod])

    daily_capacity = capacity_limit
    order_queue.sort(key=lambda x: x[0])

    processing_sequence = []
    days_present = sorted(list(set(o[0] for o in order_queue)))
    for d in days_present:
        day_orders = [ (i, o) for i, o in enumerate(order_queue) if o[0] == d ]
        day_orders.sort(key=lambda x: (x[1][1], x[1][2]))
        for item in day_orders:
            processing_sequence.append(item)

    for original_idx, order in processing_sequence:
        day_placed, qty, prod = order
        weight = weights[prod]
        current_qty = order[1]
        if current_qty <= 0: continue

        max_by_stock = current_stock[prod]
        max_by_cap = int(daily_capacity // weight)
        shipped = min(current_qty, max_by_stock, max_by_cap)

        current_stock[prod] -= shipped
        daily_capacity -= shipped * weight
        order[1] -= shipped

    order_queue = [o for o in order_queue if o[1] > 0]

    if day == 161:
        # Check if any order for SOP001L12P placed on day 161 is still in the queue
        still_backordered = [o for o in order_queue if o[0] == 161 and o[2] == 'SOP001L12P']
